values ('bbbb0003-0000-4000-8000-00000000001c', 'en', null, 'Business Strategy', 'How firms decide where to compete and how to win - reading the outside world, sizing up their own resources, and turning a point of view into coordinated action that beats rivals. Structure adapted from OpenStax Principles of Management (CC BY 4.0); all explanations original.', null, 'career', 28, true, 'business', '{bbbb0003-0000-4000-8000-000000000005}')
